#include <stdio.h>

int digit_sum(int number) {
    int sum = 0;
    while (number > 0) {
        sum += number % 10;
        number /= 10;
    }
    return sum;
}

int main() {
    printf("%d\n", digit_sum(9047));
    return 0;
}
